// 在线运行演示：浏览器原生 JavaScript（无需下载运行时）
// （需要读入数据？展开下方「标准输入」用 input() / readline() 读取。）
const nums = [3, 1, 4, 1, 5, 9, 2, 6];
const text = "the quick brown fox jumps over the lazy dog the fox";

console.log("Hello from JavaScript in the browser!");
console.log("输入 nums =", nums);
console.log("最大值 =", Math.max(...nums), "| 平均值 =", (nums.reduce((a, b) => a + b, 0) / nums.length).toFixed(2));
console.log("sqrt(2) =", Math.sqrt(2).toFixed(4));

const counter = {};
for (const word of text.split(" ")) counter[word] = (counter[word] ?? 0) + 1;
const top3 = Object.entries(counter).sort((a, b) => b[1] - a[1]).slice(0, 3);
console.log("词频 Top3 =", top3);

