// 在线运行演示：TypeScript（CDN 加载编译器，擦除类型后在浏览器执行）
interface Person {
  name: string;
  age: number;
}

const nums: number[] = [3, 1, 4, 1, 5, 9, 2, 6];
const people: Person[] = [
  { name: "Ada", age: 36 },
  { name: "Linus", age: 25 },
  { name: "Grace", age: 45 },
];

function maxBy<T>(items: T[], score: (item: T) => number): T {
  return items.reduce((best, item) => (score(item) > score(best) ? item : best));
}

console.log("Hello from TypeScript in the browser!");
console.log("最大值 =", Math.max(...nums), "| 平均值 =", (nums.reduce((a, b) => a + b, 0) / nums.length).toFixed(2));
console.log("最年长 =", maxBy(people, (p) => p.age));
